/* @lc app=leetcode id=3361 lang=kotlin */ class Solution { fun shiftDistance(s: String, t: String, nextCost: IntArray, previousCost: IntArray): Long = s.indices.sumOf { i -> (s[i] - 'a').let { a -> (t[i] - 'a').let { b -> minOf((0 until (b - a + 26) % 26).sumOf { nextCost[(a + it) % 26].toLong() }, (0 until (a - b + 26) % 26).sumOf { previousCost[(a - it + 26) % 26].toLong() }) } } } }